export const advancedLessons:AdvancedLesson[]=[
 {id:'ssd',name:'Saguaro / SSD',year:'2026',goal:"Reduce text generation waiting time",idea:"A fast assistant drafts text and a stronger model verifies it. During verification, the assistant prepares drafts for possible next-round outcomes; a correct prediction makes the next draft immediately available.",formula:String.raw`T_{\mathrm{toy}}=T_v+(1-h)T_d+T_o`,symbols:"Tv: verification time; Td: drafting time; h: probability the matching draft is ready; To: coordination overhead. This is our educational latency equation, not Saguaro’s complete performance model.",steps:["Start with speculative decoding: a small model proposes several tokens and the large model verifies them in one pass.","When sampling, accept a token with probability min(1,p/q), where p is the large model’s probability and q the draft probability. On rejection, sample from a distribution proportional to max(p−q,0).","Predict verification outcomes, including accepted-prefix length and bonus token, and prepare their continuations on other resources during verification.","Use the matching continuation when the result arrives; otherwise take a fallback path.","Compare latency, hardware cost, and acceptance rate on your requests. Successful overlap does not automatically save money."],code:'draft = propose(prefix)\nwhile not finished:\n    verification = verify_async(prefix, draft)\n    cache = prepare_likely_continuations(prefix, draft)\n    outcome = await_result(verification)\n    prefix = append_verified(prefix, outcome)\n    draft = cache.get(outcome) or fallback(prefix)',execution:"Pseudocode: you need draft and target models plus an engine coordinating execution and memory. Benchmark ordinary and speculative decoding before advanced parallelism.",application:"A support or coding assistant with shorter response waits. Measure cost per thousand requests including draft hardware.",limits:"This simulation assumes equal tokens per round and successful overlap of prepared work, ignoring hardware contention. Published results apply to the paper’s setup, not guaranteed speed on your hardware.",source:'https://arxiv.org/abs/2603.03251',sourceLabel:"Saguaro / SSD — March 2026, updated May 2026",controls:[c('h',"Ready-draft cache hit probability",0,1,.05,.8),c('draft',"Draft time (ms)",5,100,5,30),c('overhead',"Coordination overhead (ms)",0,50,1,5)],simulate:v=>({rows:[["Sequential round",80+v.draft],["Estimated overlapping round",80+(1-v.h)*v.draft+v.overhead]],unit:'ms',explanation:`Assume fixed verification time of 80 ms. Estimated speedup: ${f((80+v.draft)/(80+(1-v.h)*v.draft+v.overhead))}×; below 1 means the extra complexity is slower here.`})},
 {id:'evolve',name:'AlphaEvolve',year:'2025',goal:"Search for better programs and algorithms",idea:"Instead of accepting one generated program, maintain a population, propose edits, and use tests and measurements to select improvements. Evaluator quality is central.",formula:String.raw`P^*=\arg\min_{P:\,\mathrm{tests}(P)=1}\mathrm{runtime}(P)`,symbols:"P: candidate program; tests: correctness checks; runtime: execution time. Our educational objective minimizes time while requiring tests to pass.",steps:["Choose a clearly measurable problem, such as scheduling jobs on two workers to minimize finish time.","Create a baseline program and correctness tests separate from development examples.","Let the model propose edits, then check each candidate in an isolated environment with resource limits.","Reject incorrect results, repeat benchmarks, and retain diverse promising candidates.","Test on unseen cases and stop when search cost exceeds the value of improvement."],code:'population = [baseline]\nfor round in range(budget):\n    parent = choose_diverse_parent(population)\n    candidate = propose_code_change(parent)\n    if isolated_tests(candidate):\n        score = repeated_benchmark(candidate)\n        population = keep_best_and_diverse(population, candidate, score)\nreturn validate_on_unseen_cases(population)',execution:"Requires a code generator, evaluator, and isolated execution. This experiment searches a small set of schedules without calling a model or running AlphaEvolve.",application:"A service that improves scheduling or repeated file processing. Value comes from repeated use after the search is complete.",limits:"Test results can improve without generalizing. We establish no optimality beyond this tiny example; the original system is much broader.",source:'https://arxiv.org/abs/2506.13131',sourceLabel:"AlphaEvolve — original 2025 paper",controls:[c('budget',"Number of schedules to inspect",1,32,1,8)],simulate:v=>{const jobs=[9,8,7,6,5];let best=35;const history:[string,number][]=[];for(let m=0;m<v.budget;m++){let a=0;for(let j=0;j<5;j++)if(m&(1<<j))a+=jobs[j];best=Math.min(best,Math.max(a,35-a));history.push([`Trial ${m+1}`,best])}return{rows:history,unit:"time units",explanation:`Assign jobs of lengths 9,8,7,6,5 to two workers. Enumerate binary masks and retain the best: ${best}. Checking all 32 assignments reaches 18, which is optimal because the total is 35 and job lengths are integers.`}}},
 {id:'grpo',name:'GRPO',year:'2024',goal:"Train for better answers",idea:"Generate multiple answers to one question and compare their rewards within the group. Above-average answers receive encouragement; below-average answers receive a negative signal.",formula:String.raw`A_i=\frac{r_i-\bar r}{\sigma_r+\epsilon}\qquad L_i=\min(\rho_i A_i,\operatorname{clip}(\rho_i,1-\delta,1+\delta)A_i)`,symbols:"ri: answer reward; A: relative advantage; ρ: new-to-old policy probability ratio; δ: clipping limit. This shows the policy term; the full objective aggregates tokens and includes a KL penalty.",steps:["Collect training questions and a verifiable reward tool, such as code correctness tests.","Generate a group of answers using a fixed old policy.","Compute reward mean and standard deviation, then each answer’s advantage.","Update using a clipped objective with KL regularization toward a reference policy; do not increase probabilities without bounds.","Evaluate held-out questions and monitor reward exploitation and answer length."],code:'answers = old_policy.sample(prompt, group_size)\nrewards = verifier(answers)\nA = (rewards - mean(rewards)) / (std(rewards) + eps)\nratio = exp(new_logprob - old_logprob)\nobjective = mean(min(ratio*A, clip(ratio,1-d,1+d)*A))\nloss = -objective + beta * KL_to_reference\nbackpropagate(loss)',execution:"Pseudocode for a simplified objective, not complete training. Implementation needs a trainable model, samples, token probabilities, rewards, and GPU resources. The experiment only calculates advantages.",application:"Adapt a model to write queries or programs that pass task tests. Potential savings come from fewer retries and corrections.",limits:"Bad rewards teach bad behavior. Equal rewards produce zero advantages. Removing the critic network does not eliminate generation or training costs.",source:'https://arxiv.org/abs/2402.03300',sourceLabel:"DeepSeekMath — GRPO introduced in 2024",controls:[c('r1',"First answer reward",0,10,1,2),c('r2',"Second answer reward",0,10,1,4),c('r3',"Third answer reward",0,10,1,8)],simulate:v=>({rows:advantages([v.r1,v.r2,v.r3]).map((x,i)=>[`Advantage ${i+1}`,x]),unit:"advantage",explanation:"Positive values are above the group mean; negative values are below. These are relative training signals, not correctness probabilities or profits."})},
 {id:'moe',name:'MoE + MLA',year:'2024–2025',goal:"Reduce computation and memory",idea:"MoE sends each token to selected experts. MLA compresses attention keys and values into a latent representation. The first reduces active work; the second targets context memory.",formula:String.raw`y=\sum_{i\in\operatorname{TopK}(g(x))}\tilde g_i E_i(x)\qquad c_t=W_{DKV}h_t`,symbols:"g: routing gate; Ei: expert; normalized weights sum to 1 in this educational MoE example. ct: compressed KV representation of ht. Positional details of MLA are omitted.",steps:["The router converts token states to expert scores and selects the top k.","Run selected experts and combine weighted outputs; balanced load is needed.","Inter-device communication adds costs that can limit the benefits of reduced computation.","MLA caches compressed latent states instead of all per-head keys and values and adapts attention calculations accordingly.","Compare memory, latency, and quality on a model designed for this architecture, not arbitrary compression of another model."],code:'scores = router(hidden)\nids = top_k(scores, k)\nweights = softmax(scores[ids])\ny = sum(w * experts[i](hidden) for i,w in zip(ids,weights))\nlatent_kv = down_project(hidden)\ncache.append(latent_kv)  # architecture-specific positional state also needed',execution:"Start with an existing MoE/MLA model and a compatible engine. Building from scratch requires distributed training. Our simulation counts experts only; it does not measure MLA.",application:"Serve longer contexts or more requests when context memory or computation is the bottleneck.",limits:"k/E measures only the fraction of active experts, not speedup or total memory savings. All expert weights may remain loaded; some architectures include shared experts.",source:'https://github.com/deepseek-ai/DeepSeek-V3',sourceLabel:"DeepSeek-V3 — official report and implementation",controls:[c('k',"Active experts out of 8",1,8,1,2)],simulate:v=>({rows:[["Active experts",v.k],["Unselected experts",8-v.k]],unit:"experts",explanation:`We activate ${f(100*v.k/8)}% of experts here. This percentage must not be converted directly into an operating-cost discount.`})},
 {id:'flash',name:'FlashAttention',year:"2022 onward",goal:"Reduce data movement inside a GPU",idea:"Instead of writing the large attention matrix to external memory, compute small tiles and update softmax normalization incrementally. The attention operation is preserved up to ordinary numerical differences.",formula:String.raw`O=\operatorname{softmax}\left(\frac{QK^T}{\sqrt d}\right)V\qquad M_{\mathrm{scores}}=2n^2\;\mathrm{bytes}`,symbols:"Q: queries; K: keys; V: values; d: head dimension; n: context length. The memory formula describes one 16-bit score matrix for one head, not total model memory.",steps:["Tile Q, K, and V to fit fast memory.","Compute tile scores and their maximum to stabilize exponentials.","When merging another tile, rescale and update the running maximum, exponential sum, and weighted sum.","Return the weighted value sum divided by the exponential sum without storing a full n×n matrix in HBM.","Use a kernel supported by your hardware; verify masking, precision, and gradients, then benchmark."],code:'m, l, acc = -inf, 0, 0\nfor Kb,Vb in blocks(K,V):\n    s = Qrow @ Kb.T / sqrt(d)\n    m2 = max(m, max(s))\n    p = exp(s-m2)\n    acc = exp(m-m2)*acc + p @ Vb\n    l = exp(m-m2)*l + sum(p)\n    m = m2\noutput = acc/l',execution:"The pseudocode explains one row. Real performance requires an optimized GPU kernel; use a hardware-compatible official FlashAttention implementation, not a Python loop for speed.",application:"Train or run models on long documents. Lower memory use may allow larger batches on the same hardware.",limits:"Dense attention does not become linear; it usually remains O(n²d). Displayed memory covers one matrix and does not determine total savings.",source:'https://arxiv.org/abs/2205.14135',sourceLabel:"FlashAttention — original 2022 paper",controls:[c('n',"Context length in tokens",1024,32768,1024,8192)],simulate:v=>({rows:[["Dense score matrix for one head",2*v.n*v.n/2**20],["One 128×128 score tile",2*128*128/2**20]],unit:'MiB',explanation:"Compares one score matrix with one tile. The tile excludes Q/K/V and intermediate buffers; this is not measured FlashAttention runtime memory."})},
 {id:'compute',name:'Test-time compute',year:"2024 onward",goal:"Spend reasoning on difficult problems",idea:"Generate or revise additional solutions and check them before selection. Allocate more budget when the problem is difficult and the evaluator can identify good solutions.",formula:String.raw`P(\text{at least one correct})=1-(1-p)^N`,symbols:"p: success probability per attempt; N: attempt count. The formula assumes independent attempts and does not give the probability of selecting the correct answer.",steps:["Prepare problems with evaluable answers.","Begin with a small budget, then identify cases needing more review or search.","Generate alternatives or expand solution steps and evaluate candidates.","Select the best-rated result with time and cost caps and a stopping rule.","Compare final-answer quality and cost, not merely the presence of a correct candidate."],code:'candidates = []\nfor attempt in range(budget):\n    answer = propose_or_revise(problem, candidates)\n    candidates.append((answer, verify(answer)))\n    if reliable_stop_rule(candidates): break\nreturn select_best(candidates)',execution:"Start with a pretrained model and a test-based evaluator. This probability example calls no model and does not assume extra answers make the evaluator infallible.",application:"A code-fixing assistant spends extra attempts on failed tests rather than every simple request.",limits:"Answers are often correlated, so independence may overstate the benefit. Additional reasoning increases machine time; it may reduce human correction time.",source:'https://arxiv.org/abs/2408.03314',sourceLabel:'Scaling LLM Test-Time Compute — 2024',controls:[c('p',"Assumed success probability per attempt",0,1,.05,.25),c('n',"Number of attempts",1,32,1,4)],simulate:v=>({rows:[["One attempt succeeds",100*v.p],["At least one success exists",100*(1-(1-v.p)**v.n)]],unit:"%",explanation:`At an assumed SAR 0.02 per attempt, ${v.n} attempts cost ${f(.02*v.n)} SAR. This is an educational assumption, not provider pricing; the answer’s presence does not guarantee its selection.`})}
,...experimentalLessons];
export function valueModel(tasks:number,before:number,after:number,hour:number,run:number,setup:number){const hours=tasks*(before-after)/60,net=hours*hour-run;return{hours,net,payback:net>0?setup/net:null}}
